def rule(ctx):
    def type_score(k):
        info = ctx.types[k] if k < len(ctx.types) else None
        if info is None:
            return -1e9
        wt = info.get("work_time", 10.0)
        swt = info.get("single_work_time", wt)
        cmw = info.get("continue_max_work", 1.0)
        mt = info.get("maintenance_time", 1.0)
        ct = info.get("charge_time", 1.0)
        ot = info.get("out_travel_time", 0.0)
        rt = info.get("return_travel_time", 0.0)
        duties_per_cycle = cmw / swt if swt > 0 else 1.0
        cycle_hours = wt * duties_per_cycle
        downtime = mt + ct + ot + rt
        return cycle_hours / (downtime + 1.0)

    n_types = len(ctx.types)
    valid_new = [k for k in range(n_types) if ctx.left[k] > 0 and ctx.types[k] is not None]
    sorted_new = sorted(valid_new, key=lambda k: (-type_score(k), k))
    if ctx.gene_type is not None and ctx.gene_type in valid_new:
        sorted_new = [ctx.gene_type] + [k for k in sorted_new if k != ctx.gene_type]
    new_actions = [("new", k) for k in sorted_new]

    avail = list(ctx.available)
    if avail:
        total_wt = 0.0
        for r in avail:
            info = ctx.types[r.type] if r.type < n_types else None
            if info is not None:
                total_wt += info.get("work_time", 10.0)
            else:
                total_wt += 10.0
        avg_wt = total_wt / len(avail) if avail else 10.0
        if avg_wt <= 0:
            avg_wt = 1.0
        def robot_key(r):
            score = r.count + r.hours / avg_wt
            return (score, -r.duties_left, -r.budget, r.idx)
        sorted_avail = sorted(avail, key=robot_key)
        reuse_actions = [("reuse", r) for r in sorted_avail]
    else:
        reuse_actions = []

    try:
        cap = ctx.capacity
    except Exception:
        cap = ctx.remaining
    need_new = cap < ctx.remaining

    if not reuse_actions:
        return new_actions if new_actions else []
    if need_new and new_actions:
        return [new_actions[0]] + reuse_actions + new_actions[1:]
    else:
        return reuse_actions + new_actions
