```python
def rule(ctx):
    robots = ctx.robots
    n_robots = len(robots)
    total_count = 0
    total_hours = 0.0
    for r in robots:
        total_count += r.count
        total_hours += r.hours

    if n_robots > 0:
        avg_count = total_count / float(n_robots)
        avg_hours = total_hours / float(n_robots)
    else:
        avg_count = 0.0
        avg_hours = 0.0

    if total_count > 0:
        avg_duty = total_hours / float(total_count)
    else:
        avg_duty = 10.0
    if avg_duty < 1e-9:
        avg_duty = 10.0

    tight = ctx.capacity < ctx.remaining
    risk_weight = 1.05 if tight else 0.55

    def robot_key(r):
        p = ctx.types[r.type]
        if p is None:
            cycle = 10.0
            maint = 48.0
        else:
            cycle = p['work_time'] + p['out_travel_time'] + p['return_travel_time'] + p['charge_time']
            maint = p['maintenance_time']
        if cycle <= 1e-9:
            cycle = 1.0

        if r.duties_left > 1:
            risk = 0.0
        else:
            left = r.duties_left if r.duties_left > 0 else 1
            risk = risk_weight * (1.0 + maint / (maint + cycle * left))

        fair = (r.count - avg_count) + 0.55 * ((r.hours - avg_hours) / avg_duty)

        if r.first_maint is None:
            left = r.duties_left if r.duties_left > 0 else 1
            est = ctx.t + left * cycle
            maint_bias = -0.25 * est / (ctx.T + 1.0)
        else:
            maint_bias = 0.0

        runway = -0.02 * r.duties_left
        return (risk + fair + maint_bias + runway, -r.duties_left, r.idx)

    sorted_avail = sorted(ctx.available, key=robot_key)

    def type_key(k):
        p = ctx.types[k]
        if p is None or ctx.left[k] <= 0:
            return (9.0, 1e9, 1e9, k)

        duty = p['work_time']
        if duty <= 1e-9:
            duty = 1.0

        swork = p['single_work_time']
        if swork <= 1e-9:
            swork = 1.0

        duties_cycle = p['continue_max_work'] / swork
        if duties_cycle < 1.0:
            duties_cycle = 1.0

        cycle = duty + p['out_travel_time'] + p['return_travel_time'] + p['charge_time']
        if cycle <= 1e-9:
            cycle = 1.0

        time_to_maint = duties_cycle * cycle
        maint_before = 0.0 if time_to_maint >= ctx.remaining else 1.0

        overhead = (p['out_travel_time'] + p['return_travel_time'] + p['charge_time']) / duty
        overhead += p['maintenance_time'] / (duties_cycle * duty)

        gene_pen = 0.0 if k == ctx.gene_type else 0.05
        return (maint_before, overhead + gene_pen, -time_to_maint, k)

    type_options = []
    for k in range(len(ctx.types)):
        if ctx.types[k] is not None and ctx.left[k] > 0:
            type_options.append(k)
    type_options.sort(key=type_key)
    if not type_options:
        type_options = [ctx.gene_type]

    actions = [("reuse", r) for r in sorted_avail]
    for k in type_options:
        actions.append(("new", k))
    return actions
```

