    ntypes = len(ctx.types)
    for k in range(ntypes):
        val = type_value(k)
        if val > best_val + 1e-12 or (abs(val - best_val) <= 1e-12 and k == ctx.gene_type):
            best_val = val
            best_type = k

    if best_type is None:
        for k in range(ntypes):
            if ctx.types[k] is not None:
                best_type = k
                break
    if best_type is None:
        best_type = ctx.gene_type

    avail = ctx.available
    if not avail:
        order = []
        for k in range(ntypes):
            if ctx.types[k] is not None and ctx.left[k] > 0:
                order.append(k)
        order.sort(key=lambda k: (-type_value(k), 0 if k == ctx.gene_type else 1, k))
        if not order:
            return [("new", best_type)]
        return [("new", k) for k in order]

    tight = ctx.capacity < ctx.remaining

    def robo_key(r):
        p = ctx.types[r.type]
        w = p['work_time'] if p is not None else 1.0
        if w <= 0:
            w = 1.0
        load = r.count + (r.hours / w) * 0.35
        maint_risk = 1 if r.duties_left <= 1 else 0
        budget_short = -r.budget
        if tight:
            return (maint_risk, -r.duties_left, load, budget_short, r.ready, r.idx)
        else:
            return (maint_risk, load, budget_short, -r.duties_left, r.ready, r.idx)

    sorted_avail = sorted(avail, key=robo_key)
    actions = [("reuse", r) for r in sorted_avail]

    type_order = []
    for k in range(ntypes):
        if ctx.types[k] is not None and ctx.left[k] > 0:
            type_order.append(k)
    type_order.sort(key=lambda k: (-type_value(k), 0 if k == ctx.gene_type else 1, k))
    for k in type_order:
        actions.append(("new", k))
    if not type_order:
        actions.append(("new", best_type))
    return actions
