def rule(ctx):
    def reuse_key(r):
        p = ctx.types[r.type]
        wt = p["work_time"] if p is not None else 0
        over = wt - ctx.remaining
        if over < 0:
            over = 0
        return (r.count, -r.budget, r.hours, over, r.idx)

    actions = [("reuse", r) for r in sorted(ctx.available, key=reuse_key)]

    def new_key(k):
        p = ctx.types[k]
        if p is None or ctx.left[k] <= 0:
            return (1, float('inf'), float('inf'), float('inf'), float('inf'), k)
        wt = p["work_time"]
        over = wt - ctx.remaining
        if over < 0:
            over = 0
        dpm = p["continue_max_work"] / max(p["single_work_time"], 1e-9)
        cycle = (p["out_travel_time"] + p["return_travel_time"] + p["charge_time"]) / max(wt, 1e-9)
        maint = p["maintenance_time"] / max(dpm, 1e-9)
        return (over, maint, cycle, -dpm, -ctx.left[k], k)

    order = []
    gt = ctx.gene_type
    if 0 <= gt < len(ctx.types):
        p = ctx.types[gt]
        if p is not None and ctx.left[gt] > 0:
            wt = p["work_time"]
            if wt <= ctx.remaining:
                order.append(gt)

    for k in sorted(range(len(ctx.types)), key=new_key):
        if k not in order:
            p = ctx.types[k]
            if p is not None and ctx.left[k] > 0:
                order.append(k)

    if order:
        actions += [("new", k) for k in order]
    else:
        actions.append(("new", gt))
