def rule(ctx):
    n_all = len(ctx.robots)
    total_count = 0
    total_hours = 0.0
    if n_all:
        for r in ctx.robots:
            total_count += r.count
            total_hours += r.hours
        avg_count = total_count / float(n_all)
        avg_hours = total_hours / float(n_all)
    else:
        avg_count = 0.0
        avg_hours = 0.0

    max_duty = 1.0
    for k in range(len(ctx.types)):
        p = ctx.types[k]
        if p is not None:
            wt = p.get('work_time', 0.0)
            if wt > max_duty:
                max_duty = float(wt)

    cap = ctx.capacity
    slack = cap - ctx.remaining

    def score(r):
        p = ctx.types[r.type]
        duty = float(p.get('work_time', 10.0)) if p is not None else 10.0
        if n_all:
            balance = (r.count - avg_count) + ((r.hours - avg_hours) / max_duty)
        else:
            balance = r.count + r.hours / max_duty
        pen = 0.0
        if r.duties_left <= 1:
            maint_end = ctx.t + duty
            if p is not None:
                maint_end += float(p.get('out_travel_time', 0.0))
                maint_end += float(p.get('return_travel_time', 0.0))
                maint_end += float(p.get('maintenance_time', 0.0))
            if maint_end < ctx.T:
                if slack < duty:
                    pen += 25.0
                else:
                    pen += 0.5
            else:
                pen -= 1.0
        if slack < 0.0:
            pen -= 0.2 * r.duties_left
        return balance + pen, -r.budget, r.idx

    ordered = sorted(list(ctx.available), key=score)
    actions = [("reuse", r) for r in ordered]

    type_scores = []
    for k in range(len(ctx.types)):
        p = ctx.types[k]
        if p is not None and ctx.left[k] > 0:
            cm = float(p.get('continue_max_work', 0.0))
            mt = float(p.get('maintenance_time', 0.0))
            wt = float(p.get('work_time', 0.0))
            fit = 0.0
            if wt > ctx.remaining:
                fit = 1000.0
            type_scores.append((fit - cm * 10.0 + mt * 0.1, k))
    type_scores.sort()
    new_order = [k for sc, k in type_scores]
    gt = ctx.gene_type
    if gt is not None and gt >= 0 and gt < len(ctx.types) and ctx.types[gt] is not None and ctx.left[gt] > 0:
        if gt in new_order:
            new_order.remove(gt)
        new_order.insert(0, gt)
    for k in new_order:
        actions.append(("new", k))
    return actions
