def rule(ctx):
    def rkey(r):
        return (r.count, -r.duties_left, -r.budget, r.idx)
    ans = [("reuse", r) for r in sorted(ctx.available, key=rkey)]
    gt = ctx.gene_type
    valid = []
    for k in range(len(ctx.types)):
        if ctx.types[k] is not None and ctx.left[k] > 0:
            valid.append(k)
    def tkey(k):
        p = ctx.types[k]
        sw = p.get("single_work_time", 1.0)
        if sw is None or sw <= 0:
            sw = 1.0
        cm = p.get("continue_max_work", 0.0)
        mt = p.get("maintenance_time", 0.0)
        ct = p.get("charge_time", 0.0)
        ot = p.get("out_travel_time", 0.0)
        rt = p.get("return_travel_time", 0.0)
        wt = p.get("work_time", 0.0)
        cycle_hours = (cm / sw) * wt if wt > 0 else cm / sw
        recovery = mt + ct + ot + rt
        return (-cycle_hours, recovery, -wt, k)
    if ctx.capacity < ctx.remaining:
        valid.sort(key=tkey)
    else:
        def tkey_gene(k):
            return (0 if k == gt else 1, tkey(k))
        valid.sort(key=tkey_gene)
    for k in valid:
        ans.append(("new", k))
    if not valid:
        ans.append(("new", gt))
    return ans
