def rule(ctx):
    n_all = len(ctx.robots)
    if n_all:
        total_count = 0
        total_hours = 0.0
        for r in ctx.robots:
            total_count += r.count
            total_hours += r.hours
        avg_count = total_count / float(n_all)
        avg_hours = total_hours / float(n_all)
    else:
        avg_count = 0.0
        avg_hours = 0.0

    max_duty = 1.0
    min_duty = 1000000000.0
    for k in range(len(ctx.types)):
        p = ctx.types[k]
        if p is not None:
            wt = float(p.get('work_time', 0.0))
            if wt > max_duty:
                max_duty = wt
            if wt > 0.0 and wt < min_duty:
                min_duty = wt
    if min_duty > 100000000.0:
        min_duty = max_duty

    cap = ctx.capacity
    slack = cap - ctx.remaining
    tight = slack < (0.6 * max_duty)
    progress = ctx.t / max(1.0, float(ctx.T))

    if progress < 0.25:
        w_load = 0.55
        w_idle = 1.10
        w_maint = 0.35
    elif progress < 0.75:
        w_load = 1.00
        w_idle = 0.55
        w_maint = 0.75
    else:
        w_load = 1.35
        w_idle = 0.25
        w_maint = 1.25

    def robot_key(r):
        p = ctx.types[r.type] if r.type >= 0 and r.type < len(ctx.types) else None
        if p is not None:
            duty = float(p.get('work_time', 10.0))
            out = float(p.get('out_travel_time', 0.0))
            ret = float(p.get('return_travel_time', 0.0))
            charge = float(p.get('charge_time', 0.0))
            maint = float(p.get('maintenance_time', 0.0))
        else:
            duty = 10.0
            out = 0.0
            ret = 0.0
            charge = 0.0
            maint = 0.0

        if n_all:
            load = (r.count - avg_count) + ((r.hours + duty) - avg_hours) / max_duty
        else:
            load = r.count + (r.hours + duty) / max_duty

        if r.last_end is None:
            idle = 1.6
        else:
            idle = (ctx.t - r.last_end) / max(1.0, float(ctx.T))
            if idle < 0.0:
                idle = 0.0
            if idle > 1.5:
                idle = 1.5

        maint_pen = 0.0
        if r.duties_left <= 1:
            maint_end = ctx.t + out + duty + ret + maint
            if maint_end < ctx.T:
                if tight:
                    maint_pen = 3.0 + (ctx.T - maint_end) / max(1.0, ctx.remaining)
                else:
                    maint_pen = -0.35 - 0.35 * (ctx.T - maint_end) / max(1.0, ctx.T)
            else:
                if ctx.remaining > duty * 2.0:
                    maint_pen = 2.0 + (maint_end - ctx.T) / max(1.0, ctx.remaining)
                else:
                    maint_pen = -2.0

        fit_pen = 0.0
        if duty > ctx.remaining + 1e-9:
            fit_pen = 8.0 + (duty - ctx.remaining) / max(1.0, ctx.remaining)

        fm_pen = 0.0
        if r.first_maint is not None:
            fm_pen = -0.05

        score = w_load * load + w_maint * maint_pen + fit_pen + fm_pen - w_idle * idle
        return (score, -r.budget, -idle, r.idx)

    ordered = sorted(list(ctx.available), key=robot_key)
    actions = [("reuse", r) for r in ordered]

    type_scores = []
    for k in range(len(ctx.types)):
        p = ctx.types[k]
        if p is not None and ctx.left[k] > 0:
            duty = float(p.get('work_time', 10.0))
            cm = float(p.get('continue_max_work', 1.0))
            sw = float(p.get('single_work_time', duty))
            if sw <= 0.0:
                sw = max(1.0, duty)
            out = float(p.get('out_travel_time', 0.0))
            ret = float(p.get('return_travel_time', 0.0))
            charge = float(p.get('charge_time', 0.0))
            maint = float(p.get('maintenance_time', 0.0))

            dpm = cm / max(1.0, sw)
            if dpm < 1.0:
                dpm = 1.0
            cycle_time = dpm * (duty + out + ret + charge) + maint
            efficiency = (dpm * duty) / max(1.0, cycle_time)

            over = 0.0
            if duty > ctx.remaining + 1e-9:
                over = 50.0 + (duty - ctx.remaining) / max(1.0, ctx.remaining)

            remainder_pen = 0.0
            after = ctx.remaining - duty
            if after > 0.0 and after < min_duty:
                remainder_pen = 2.0 + (min_duty - after) / max(1.0, min_duty)

            score = over + remainder_pen - 4.0 * efficiency + 0.02 * maint / max(1.0, cm)
            type_scores.append((score, k))

    type_scores.sort()
    new_order = [k for sc, k in type_scores]

    gt = ctx.gene_type
    if gt is not None and gt >= 0 and gt < len(ctx.types) and ctx.types[gt] is not None and ctx.left[gt] > 0:
        if gt in new_order:
            new_order.remove(gt)
        new_order.insert(0, gt)

    if not new_order:
        if gt is not None:
            new_order.append(gt)
        elif len(ctx.types) > 0:
            new_order.append(0)

    for k in new_order:
        actions.append(("new", k))
    return actions
