        avg_hours = 0.0

    def reuse_key(r):
        p = ctx.types[r.type]
        w = p["work_time"]
        pc = r.count + 1
        ph = r.hours + w

        risk = 0.0
        if r.first_maint is None:
            if r.duties_left <= 1:
                risk = 2.0
            elif r.duties_left <= 2:
                risk = 1.0

        if w > ctx.remaining:
            fit_pen = 10.0 + (w - ctx.remaining) * 0.01
        else:
            fit_pen = 0.0

        score = (pc + 1.0) / (avg_count + 1.0)
        score += 0.5 * (ph + 1.0) / (avg_hours + 1.0)
        score += 0.25 * risk + fit_pen
        score -= 0.002 * r.duties_left + 0.0001 * r.budget

        return (score, pc, ph, -r.duties_left, -r.budget, r.idx)

    reuses = sorted(ctx.available, key=reuse_key)

