        p = ctx.types[k]
        w = p["work_time"]
        rem = ctx.remaining

        if w <= rem:
            fit = 0
            over = rem - w
        else:
            fit = 1
            over = w - rem

        single = p["single_work_time"]
        if single > 0:
            duties = p["continue_max_work"] / single
        else:
            duties = 0.0

        cycle_hours = duties * w
        overhead = p["out_travel_time"] + p["return_travel_time"] + p["charge_time"]
        cycle_time = cycle_hours + duties * overhead + p["maintenance_time"]
        eff = cycle_hours / cycle_time if cycle_time > 0 else 0.0

        return (fit, over, -eff, -cycle_hours,
                p["maintenance_time"] + p["charge_time"], k)

    others = []
    for k in range(len(ctx.types)):
        p = ctx.types[k]
        if p is None or ctx.left[k] <= 0:
            continue
        if k == ctx.gene_type:
            continue
        others.append(k)

    others.sort(key=type_key)
    for k in others:
        new_types.append(k)

    return [("reuse", r) for r in reuses] + [("new", k) for k in new_types]
