{Score available robots by horizon-fit penalty then by a projected combined duty-count/hours load with maintenance-slack and budget tie-breakers, and rank new robot types by gene type first, then horizon fit, amortized cycle/maintenance overhead, endurance, and remaining type capacity.}

```python
def rule(ctx):
    total_wt = 0.0
    n_types = 0
    for k in range(len(ctx.types)):
        p = ctx.types[k]
        if p is not None:
            total_wt += p["work_time"]
            n_types += 1
    avg_wt = total_wt / n_types if n_types > 0 else 10.0

    def rkey(r):
        p = ctx.types[r.type]
        wt = p["work_time"] if p is not None else avg_wt
        over = wt - ctx.remaining
        if over < 0:
            over = 0
        load = avg_wt * (r.count + 1) + r.hours + wt
        return (over, load, -r.duties_left, -r.budget, r.idx)

    actions = [("reuse", r) for r in sorted(ctx.available, key=rkey)]

    def tkey(k):
        p = ctx.types[k]
        if p is None or ctx.left[k] <= 0:
            return (1e9, 0.0, 0.0, 0.0, k)
        wt = p["work_time"]
        over = wt - ctx.remaining
        if over < 0:
            over = 0
        single = max(p["single_work_time"], 1e-9)
        dpm = p["continue_max_work"] / single
        cycle = p["out_travel_time"] + p["return_travel_time"] + p["charge_time"]
        maint_per_duty = p["maintenance_time"] / max(dpm, 1e-9)
        overhead = (cycle + maint_per_duty) / max(wt, 1e-9)
        return (over, overhead, -dpm, -ctx.left[k], k)

    order = []
    gt = ctx.gene_type
    if 0 <= gt < len(ctx.types):
        p = ctx.types[gt]
        if p is not None and ctx.left[gt] > 0:
            order.append(gt)

    for k in sorted(range(len(ctx.types)), key=tkey):
        if k not in order:
            p = ctx.types[k]
            if p is not None and ctx.left[k] > 0:
                order.append(k)

    if order:
        actions += [("new", k) for k in order]
    else:
        actions.append(("new", gt))

    return actions
```

{Use a weighted load score that favors available robots by lower count and duty-hour load, then by greater remaining maintenance budget and duties, and when opening a new robot prefer the feasible type with the highest continuous-work-to-maintenance-overhead ratio, using the gene-chosen type only as a tie-break.}
```python
def rule(ctx):
    def robot_key(r):
        t = ctx.types[r.type]
        cmw = t["continue_max_work"] if t["continue_max_work"] > 0 else 1.0
        swt = t["single_work_time"]
        cycle_duties = cmw / (swt + 1.0) if swt > 0 else 1.0
        budget_ratio = r.budget / (cmw + 1.0)
        left_ratio = r.duties_left / (1.0 + cycle_duties)
        load = 0.60 * r.count + 0.40 * (r.hours / 10.0)
        return (load, -budget_ratio, -left_ratio, r.idx)

    actions = []
    if ctx.available:
        best = min(ctx.available, key=robot_key)
        actions.append(("reuse", best))
        for r in ctx.available:
            if r is not best:
                actions.append(("reuse", r))

    def new_key(k):
        t = ctx.types[k]
        overhead = (
            t["maintenance_time"]
            + t["charge_time"]
            + t["out_travel_time"]
            + t["return_travel_time"]
            + 1.0
        )
        cycle = t["continue_max_work"] if t["continue_max_work"] > 0 else 1.0
        return (-(cycle / overhead), -t["single_work_time"], k != ctx.gene_type, k)

    candidates = []
    for k, t in enumerate(ctx.types):
        if t is not None and ctx.left[k] > 0:
            candidates.append(k)

    if candidates:
        best_new = min(candidates, key=new_key)
        actions.append(("new", best_new))
        others = []
        for k in candidates:
            if k != best_new:
                others.append(k)
        others.sort(key=lambda k: (k != ctx.gene_type, k))
        for k in others:
            actions.append(("new", k))

    if not actions:
        actions.append(("new", ctx.gene_type))

    return actions
```

