{Use an accumulated blocking-time utilization balance with a maintenance-risk guard to order reusable robots, and rank new types by horizon fit plus amortized cycle-and-maintenance cost per duty hour with a mild genome-type bias.}
```python
def rule(ctx):
    def reuse_key(r):
        p = ctx.types[r.type]
        if p is None:
            wt = 10.0
            cyc = 10.0
            mt = 0.0
        else:
            wt = p["work_time"]
            if wt <= 0:
                wt = 1e-9
            cyc = p["out_travel_time"] + wt + p["return_travel_time"] + p["charge_time"]
            mt = p["maintenance_time"]

        risk = 0
        if p is not None:
            if r.duties_left <= 1:
                risk = 2
            elif r.duties_left <= 2:
                risk = 1
            if ctx.remaining - wt <= mt:
                risk = 0

        block = (r.count + 1) * cyc
        return (risk, block, cyc, r.hours / wt, -r.duties_left, r.idx)

    reuses = sorted(ctx.available, key=reuse_key)

    remaining = ctx.remaining
    if remaining < 0:
        remaining = 0.0

    def new_key(k):
        p = ctx.types[k]
        if p is None or ctx.left[k] <= 0:
            return (1, 1e9, 1e9, 1e9, 1e9, k)

        wt = p["work_time"]
        if wt <= 0:
            wt = 1e-9

        single = p["single_work_time"]
        if single <= 0:
            single = 1e-9

        cmw = p["continue_max_work"]
        if cmw <= 0:
            cmw = 1.0

        dpm = cmw / single
        if dpm < 1.0:
            dpm = 1.0

        cyc = p["out_travel_time"] + wt + p["return_travel_time"] + p["charge_time"]
        maint = p["maintenance_time"]
        cost = (cyc + maint / dpm) / wt

        over = wt - remaining
        if over < 0:
            over = 0.0

        waste = (remaining % wt) / wt if wt > 0 else 0.0
        gene_pen = 0.0 if k == ctx.gene_type else 0.5

        return (over, cost + waste * 2.0 + gene_pen, -dpm, cyc, -ctx.left[k], k)

    new_types = []
    for k in range(len(ctx.types)):
        p = ctx.types[k]
        if p is not None and ctx.left[k] > 0:
            new_types.append(k)
    new_types.sort(key=new_key)

    actions = [("reuse", r) for r in reuses]
    for k in new_types:
        actions.append(("new", k))

    if not actions:
        gt = ctx.gene_type
        if gt is None or gt < 0 or gt >= len(ctx.types):
            gt = 0
        actions.append(("new", gt))

    return actions
