{Use a three-level capacity-pressure policy that ranks available robots by horizon-fit and either maintenance runway or count/hour fairness, and ranks new types by horizon fit, maintenance-cycle work yield/efficiency, and a gene-type bias.}
```python
def rule(ctx):
    rem = ctx.remaining
    cap = ctx.capacity
    slack = cap - rem

    if slack < 0.0:
        mode = 2
    elif slack < 0.15 * max(rem, 1.0):
        mode = 1
    else:
        mode = 0

    def rkey(r):
        p = ctx.types[r.type]
        wt = p["work_time"] if p is not None else 0.0
        over = wt - rem
        if over < 0.0:
            over = 0.0
        if mode == 2:
            return (over, -r.budget, -r.duties_left, r.count, r.hours, r.idx)
        if mode == 1:
            return (over, -r.duties_left, -r.budget, r.count, r.hours, r.idx)
        return (over, r.count, r.hours, -r.duties_left, -r.budget, r.idx)

    actions = [("reuse", r) for r in sorted(ctx.available, key=rkey)]

    def tkey(k):
        p = ctx.types[k]
        if p is None or ctx.left[k] <= 0:
            return (1, 0, 0, 0, 0, 0, 0, k)
        wt = p["work_time"]
        sw = p["single_work_time"]
        cm = p["continue_max_work"]
        mt = p["maintenance_time"]
        ct = p["charge_time"]
        ot = p["out_travel_time"]
        rt = p["return_travel_time"]

        over = wt - rem
        if over < 0.0:
            over = 0.0

        tail = 0.0
        if wt > 0.0 and rem >= wt:
            tail = (wt - (rem % wt)) % wt

        dpm = cm / max(sw, 1e-9)
        total = dpm * wt
        cycle = total + mt + ct + ot + rt
        eff = total / max(cycle, 1e-9) if total > 0.0 else 0.0
        gene = 0 if k == ctx.gene_type else 1

        if mode == 2:
            return (over, -total, mt, gene, -eff, -ctx.left[k], k)
        if mode == 1:
            return (over, -dpm, -total, gene, mt, -eff, k)
        return (over, gene, -eff, tail, mt, -ctx.left[k], k)

    valid = [k for k in range(len(ctx.types)) if ctx.types[k] is not None and ctx.left[k] > 0]
    valid.sort(key=tkey)
    for k in valid:
        actions.append(("new", k))
    if not valid:
        actions.append(("new", ctx.gene_type))
    return actions
